#include "../sc-cuda/device_sc.cu"
#include <vector>
#include <fstream>
#include <chrono>
#include <algorithm>
#include <string>
extern "C" void*sc_host_create(int,int);extern "C" int*sc_host_data(void*);extern "C" int*sc_host_flags(void*);extern "C" void sc_host_reset(void*,const int*,int,int);extern "C" void sc_host_start(void*,int,float);extern "C" void sc_host_wait(void*);extern "C" void sc_host_destroy(void*);
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
std::vector<int>load(const char*n){std::ifstream in(std::string(SC_ROOT)+"/"+n,std::ios::binary|std::ios::ate);if(!in)exit(3);size_t bytes=in.tellg();if(bytes%4)exit(4);std::vector<int>v(bytes/4);in.seekg(0);if(!in.read((char*)v.data(),bytes))exit(5);return v;}
std::vector<int>get(int*p,size_t n){std::vector<int>v(n);ck(cudaMemcpy(v.data(),p,n*4,cudaMemcpyDefault));return v;}
void append(std::vector<int>&a,const std::vector<int>&b){a.insert(a.end(),b.begin(),b.end());}
struct Case{int n,ai,tasks,cut,padded,gpad;size_t prefix_pos;std::vector<int>input;void*host;int*data,*flags,*dbase,*ddata,*fbase,*dflags;};
void reset(Case&c){sc_host_reset(c.host,c.input.data(),c.n,c.cut);std::vector<int>d(c.gpad+2,-777),f(c.tasks+3,-777);std::copy(c.data+c.cut*8192,c.data+c.padded,d.begin()+1);std::copy(c.flags,c.flags+c.tasks+1,f.begin()+1);ck(cudaMemcpy(c.dbase,d.data(),d.size()*4,cudaMemcpyDefault));ck(cudaMemcpy(c.fbase,f.data(),f.size()*4,cudaMemcpyDefault));ck(cudaDeviceSynchronize());}
void run(Case&c){StreamCompaction<<<4,256,1028>>>(c.n,0,c.tasks,c.ai*.1f,c.ddata,c.ddata,c.dflags);ck(cudaGetLastError());sc_host_start(c.host,c.n,c.ai*.1f);ck(cudaDeviceSynchronize());sc_host_wait(c.host);}
int main(){auto f=load("fixtures_i32.bin"),oracle=load("oracle_i32.bin");size_t pos=1;std::vector<Case>cases;for(int ci=0;ci<f[0];ci++){Case c;c.n=f.at(pos++);c.ai=f.at(pos++);c.prefix_pos=pos;c.input.assign(f.begin()+pos,f.begin()+pos+c.n);pos+=c.n;c.tasks=(c.n+8191)/8192;c.cut=(int)(c.tasks*(c.ai*.1f));c.padded=c.tasks*8192;c.gpad=(c.tasks-c.cut)*8192;c.host=sc_host_create(c.padded,c.tasks);c.data=sc_host_data(c.host);c.flags=sc_host_flags(c.host);ck(cudaMalloc(&c.dbase,(c.gpad+2)*4));c.ddata=c.dbase+1;ck(cudaMalloc(&c.fbase,(c.tasks+3)*4));c.dflags=c.fbase+1;cases.push_back(c);}for(auto&c:cases){reset(c);run(c);}for(int trial=1;trial<=5;trial++){auto payload=f;std::vector<int>results;std::vector<double>times;double total=0;bool ok=true;for(auto&c:cases){reset(c);auto before=get(c.ddata,c.gpad);std::copy(c.data,c.data+c.n,payload.begin()+c.prefix_pos);int logicalgpu=c.n-c.cut*8192;if(logicalgpu>0)std::copy(before.begin(),before.begin()+logicalgpu,payload.begin()+c.prefix_pos+c.cut*8192);for(int j=std::max(logicalgpu,0);j<c.gpad;j++)ok &=before[j]==0;auto start=std::chrono::steady_clock::now();run(c);double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();times.push_back(elapsed);total+=elapsed;auto gf=get(c.dflags,c.tasks+1);int cpucount=c.cut==0?0:c.flags[c.cut]-2;int gpucount=gf[c.tasks]-1;int count=cpucount+gpucount;if(count<0||count>c.n)return 6;if(c.gpad)ck(cudaMemcpy(c.data+cpucount,c.ddata,c.gpad*4,cudaMemcpyDefault));results.push_back(count);results.insert(results.end(),c.data,c.data+count);results.insert(results.end(),c.flags,c.flags+c.tasks+1);append(results,gf);results.push_back(c.data[-1]);results.push_back(c.data[c.padded]);results.push_back(c.flags[-1]);results.push_back(c.flags[c.tasks+1]);append(results,get(c.dbase,1));append(results,get(c.ddata+c.gpad,1));append(results,get(c.fbase,1));append(results,get(c.dflags+c.tasks+1,1));}ok &=payload==f&&results==oracle;append(payload,results);std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream out(path,std::ios::binary);out.write((char*)payload.data(),payload.size()*4);out.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"max_rel_error\":null,\"timing_region\":\"sum15_static_CPU_GPU_compaction_compute_threadspawn_contextjoin\",\"jit_excluded\":true,\"internal_repeats\":1,\"timed_kernel_calls\":15,\"CPU_workers_per_case\":4,\"case_times_seconds\":[",trial,total,ok?"true":"false",payload.size(),ok?0:1);for(size_t j=0;j<times.size();j++)printf("%s%.17g",j?",":"",times[j]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),payload.size());if(!ok)return 7;}for(auto&c:cases){ck(cudaFree(c.dbase));ck(cudaFree(c.fbase));sc_host_destroy(c.host);}return 0;}
